  const bridge={start,showText:()=>show(true),resize(height,owner=frame){resizeOwner(height,owner);},close};
  function dispose(){if(disposed)return;disposed=true;epoch++;const row=eligible();if(frame&&mountedTarget&&row&&shownToken===`${epoch-1}:${row.id}:${row.swipe}:${row.message}`&&mountedTarget===frame.parentNode){if(originalNodes.length)mountedTarget.replaceChildren(...originalNodes);else mountedTarget.textContent=row.message;}observer?.disconnect();close();closeReplay();for(const x of stops)x.stop();if(host.MikageOpeningScreen===api)delete host.MikageOpeningScreen;}
